insert into public.schemes (source_serial_no, slug, name, ministry_department, category_tags, education_level, family_income_ceiling, eligibility_official, eligibility_plain, benefits, documents_required, application_mode, official_apply_url, verification_source_url, application_window, last_verified_date, researcher_name, notes_flags)
values
(44, 'pm-usp-csss', 'Pradhan Mantri Uchchatar Shiksha Protsahan (PM-USP) Central Sector Scheme of Scholarship for College and University Students', 'Department of Higher Education, Ministry of Education', ARRAY['Education', 'Scholarship', 'College', 'University']::text[], 'Regular undergraduate, postgraduate, and eligible professional degree courses', 'Gross parental/family income not exceeding ₹4,50,000 per annum', 'Fresh applicants must be in the relevant top-percentile list after Class XII, pursue a regular course rather than correspondence or distance study, meet the family-income ceiling, and not receive another scholarship or fee reimbursement. Renewal requires promotion, at least 50% marks, and 75% attendance.', 'You may qualify if you are in the relevant Class XII top-percentile list, are studying a regular recognized course, meet the income limit, and do not receive another scholarship.', '₹12,000 per annum for the first three undergraduate years; ₹20,000 per annum at postgraduate level and eligible fourth/fifth professional-course years; paid through Aadhaar-seeded bank-account DBT.', ARRAY['Aadhaar or OTR details', 'Class XII mark sheet', 'Family income certificate', 'Caste certificate where applicable', 'Disability certificate where applicable', 'Bank account/Aadhaar-seeding details', 'Previous-year mark sheet for renewal']::text[], 'Online through the National Scholarship Portal', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/FAQ_DOHE_CSSS.pdf', 'The active NSP cycle and cut-off dates must be checked before applying.', '2026-08-28', 'SchemeSetu source pass', 'The official 2025-26 FAQ states top-percentile, ₹4.5 lakh income, regular-course, 50% marks, and 75% attendance conditions; display the live NSP dates.'),
(45, 'mgnrega', 'Mahatma Gandhi National Rural Employment Guarantee Scheme', 'Ministry of Rural Development', ARRAY['Employment', 'Rural Development', 'Livelihoods']::text[], NULL, NULL, 'Adult members of a rural household willing to do unskilled manual work may demand employment under the Act through the local Gram Panchayat.', 'If you are an adult living in a rural household and want permitted manual work, your household can request employment through the local Panchayat.', 'Employment is to be provided within the statutory framework, with up to 100 days of work per rural household per financial year subject to applicable rules and demand.', ARRAY['Job card or registration details', 'Identity and residence proof as required by the local authority', 'Bank or postal account details for payment']::text[], 'Offline through Gram Panchayat and official MGNREGA channels', 'https://nrega.nic.in/', 'https://eshram.gov.in/employment-schemes', 'Demand-driven; local implementation applies.', '2026-08-27', 'SchemeSetu source pass', 'Wage rates vary by notified area and year; do not hard-code a single national wage rate.'),
(46, 'pm-svanidhi', 'Prime Minister Street Vendor''s AtmaNirbhar Nidhi (PM SVANidhi)', 'Ministry of Housing and Urban Affairs', ARRAY['Livelihoods', 'Urban', 'Street Vendors', 'Finance']::text[], NULL, NULL, 'Street vendors holding a Certificate of Vending or identity card issued by an Urban Local Body, including eligible surveyed vendors awaiting documentation under applicable rules.', 'You may qualify if you are an eligible urban street vendor recognized by the local authority.', 'Working-capital support, incentives for regular repayment, and incentives for digital transactions under the current scheme terms.', ARRAY['Certificate of Vending or vendor identity card', 'Identity proof', 'Bank account details', 'Local-body or survey record where applicable']::text[], 'Online through the official PM SVANidhi portal or assisted local-body channel', 'https://pmsvanidhi.mohua.gov.in/login', 'https://eshram.gov.in/employment-schemes', 'Subject to current programme terms and lending windows.', '2026-08-27', 'SchemeSetu source pass', 'Verify current tranche amounts before publication; the e-Shram page confirms purpose but not all current loan terms.'),
(47, 'pradhan-mantri-kaushal-vikas-yojana', 'Pradhan Mantri Kaushal Vikas Yojana', 'Ministry of Skill Development and Entrepreneurship', ARRAY['Skills', 'Employment', 'Youth']::text[], 'Eligible school-leaver and youth training pathways', NULL, 'Indian nationals meeting the current programme and course requirements; the official e-Shram listing describes eligibility examples including 10th-pass or 12th-dropout candidates and an 18–45 age range.', 'You may qualify if you are an Indian youth who meets the current course, age, and training-centre requirements.', 'Skill training, assessment, certification, and support through approved training centres under the current programme version.', ARRAY['Identity proof', 'Education proof where required', 'Bank details where the selected programme provides a financial benefit']::text[], 'Online or through an approved training centre', 'https://www.pmkvyofficial.org/', 'https://eshram.gov.in/employment-schemes', 'Course and centre availability varies.', '2026-08-27', 'SchemeSetu source pass', 'Verify active programme version, course list, and current age rules before publication.'),
(48, 'prime-minister-employment-generation-programme', 'Prime Minister''s Employment Generation Programme', 'Ministry of Micro, Small and Medium Enterprises; KVIC implementation', ARRAY['Enterprise', 'Employment', 'MSME', 'Livelihoods']::text[], 'At least Class VIII for larger projects under the cited eligibility rule', NULL, 'Indian individuals aged above 18 may apply for eligible new enterprise projects; at least Class VIII qualification is required for projects above the stated manufacturing or service cost thresholds.', 'You may qualify if you are an adult planning an eligible new micro-enterprise and meet the education requirement for a larger project.', 'Financial assistance through a credit-linked subsidy programme for setting up new enterprises.', ARRAY['Identity proof', 'Address proof', 'Project report', 'Education certificate where applicable', 'Bank and enterprise documents']::text[], 'Online through the official KVIC PMEGP portal', 'https://www.kviconline.gov.in/pmegpeportal/jsp/pmegponline.jsp', 'https://eshram.gov.in/employment-schemes', 'Subject to current KVIC and lending-channel availability.', '2026-08-27', 'SchemeSetu source pass', 'Verify current subsidy percentages, project ceilings, and applicant contribution before publication.'),
(49, 'pradhan-mantri-jan-dhan-yojana', 'Pradhan Mantri Jan-Dhan Yojana', 'Department of Financial Services, Ministry of Finance', ARRAY['Finance', 'Financial Inclusion', 'Insurance', 'Pension']::text[], NULL, NULL, 'A person who does not have another bank account may open a basic savings bank deposit account through a bank branch or Business Correspondent outlet.', 'You may qualify if you are an unbanked person seeking a basic bank account.', 'No minimum-balance requirement, interest on deposits, RuPay debit card, eligible accidental-insurance cover, overdraft facility for eligible account holders, and access to DBT-linked schemes.', ARRAY['Identity and address proof accepted by the bank', 'Aadhaar where used for KYC', 'Photograph', 'Mobile number']::text[], 'Offline through a bank branch or Business Correspondent outlet', 'https://pmjdy.gov.in/scheme', 'https://pmjdy.gov.in/scheme', 'Open subject to bank and KYC processes.', '2026-08-27', 'SchemeSetu source pass', 'Verify current overdraft and insurance terms at the participating bank before application.'),
(50, 'pradhan-mantri-ujjwala-yojana-2', 'Pradhan Mantri Ujjwala Yojana 2.0', 'Ministry of Petroleum and Natural Gas', ARRAY['Energy', 'Household Support', 'Women']::text[], NULL, 'Poor household based on prescribed deprivation declaration', 'A woman aged 18 or above from an eligible poor household, with no other LPG connection from an Oil Marketing Company in the same household.', 'You may qualify if you are an adult woman in an eligible poor household that does not already have an LPG connection.', 'Deposit-free LPG connection assistance, with current connection assistance terms including cylinder, regulator, hose, consumer card, inspection/installation charges, and a first refill and stove under the current PMUY terms.', ARRAY['KYC application form', 'Applicant Aadhaar', 'Address proof where Aadhaar address differs', 'Ration card or family-composition proof', 'Adult family members’ Aadhaar', 'Bank passbook or cancelled cheque', 'Deprivation declaration']::text[], 'Online through an official Oil Marketing Company portal or offline through the nearest LPG distributor', 'https://www.pmuy.gov.in/', 'https://www.pmuy.gov.in/', 'Subject to current PMUY availability and distributor process.', '2026-08-27', 'SchemeSetu source pass', 'Connection assistance and refill terms can change; show the live PMUY page before application.'),
(51, 'pradhan-mantri-matru-vandana-yojana', 'Pradhan Mantri Matru Vandana Yojana', 'Ministry of Women and Child Development', ARRAY['Women', 'Maternity', 'Health', 'Nutrition']::text[], NULL, 'Eligibility includes disadvantaged categories and current PMMVY criteria', 'Eligible pregnant and lactating mothers under current PMMVY rules, implemented as a Centrally Sponsored Maternity Benefits Scheme; category and documentation conditions apply.', 'You may qualify if you are a pregnant or lactating mother who meets the current PMMVY category and documentation rules.', '₹5,000 through DBT for the first child and ₹6,000 for an eligible second child when the second child is a girl, subject to current scheme conditions.', ARRAY['Identity and bank/post-office account details', 'Pregnancy and birth-related records', 'Category or vulnerability proof where applicable', 'Child and mother records required by the implementing authority']::text[], 'Through the prescribed Anganwadi, health-facility, or official PMMVY channel', 'https://www.spniwcd.wcd.gov.in/pradhan-mantri-matru-vandana-yojna', 'https://www.spniwcd.wcd.gov.in/pradhan-mantri-matru-vandana-yojna', 'Apply within the current PMMVY time limits communicated by the implementing channel.', '2026-08-27', 'SchemeSetu source pass', 'The official page states Odisha and Telangana are not implementing PMMVY; surface this jurisdiction exception.'),
(52, 'pradhan-mantri-jeevan-jyoti-bima-yojana', 'Pradhan Mantri Jeevan Jyoti Bima Yojana', 'Department of Financial Services, Ministry of Finance', ARRAY['Insurance', 'Financial Security', 'Family Support']::text[], NULL, NULL, 'Savings bank account holders aged 18–50 in participating banks may join; a person with multiple accounts may join through only one account, and Aadhaar is the primary KYC for the bank account.', 'You may qualify if you are 18–50 and hold an eligible savings account with a participating bank.', 'One-year renewable life insurance cover for death due to any reason, subject to the scheme rules and insurer terms.', ARRAY['Savings bank account details', 'Aadhaar or bank KYC', 'Consent-cum-declaration form', 'Claim form for beneficiaries where applicable']::text[], 'Through a participating bank or approved channel', 'https://www.indiapost.gov.in/insurance-services/pmjjby', 'https://www.indiapost.gov.in/insurance-services/pmjjby', 'Annual enrollment/renewal cycle as communicated by the participating bank.', '2026-08-27', 'SchemeSetu source pass', 'Confirm current premium and cover amount from the latest official rules/FAQ before publication.'),
(53, 'pradhan-mantri-awas-yojana-gramin', 'Pradhan Mantri Awaas Yojana - Gramin', 'Ministry of Rural Development', ARRAY['Housing', 'Rural Development', 'Basic Amenities']::text[], NULL, NULL, 'Rural houseless households and households living in eligible kutcha or dilapidated houses, identified through housing-deprivation parameters and verified through the prescribed Gram Sabha and programme process.', 'You may be considered if your rural household is houseless or lives in an eligible kutcha or dilapidated house and passes the official deprivation and verification process.', 'Financial assistance for a pucca house, with different assistance levels for plain and difficult areas, plus convergence support for sanitation, wage labour, LPG, water, and electricity under applicable programme rules.', ARRAY['Beneficiary and household details', 'Aadhaar and consent where required', 'Bank or post-office account details', 'Housing and land details', 'Documents requested by the Gram Panchayat or programme authority']::text[], 'Through the official PMAY-G/Gram Panchayat beneficiary-registration process', 'https://pmayg.nic.in/netiay/home.aspx', 'https://www.myscheme.gov.in/schemes/pmay-g', 'Beneficiary identification and registration follow programme and State/UT implementation cycles.', '2026-08-27', 'SchemeSetu source pass', 'The captured myScheme page includes historical extension dates; recheck the current PMAY-G phase and assistance rates before publication.'),
(54, 'pradhan-mantri-awas-yojana-urban', 'Pradhan Mantri Awas Yojana - Urban', 'Ministry of Housing and Urban Affairs', ARRAY['Housing', 'Urban Development', 'EWS', 'LIG']::text[], NULL, 'Income band depends on the active PMAY-U 2.0 vertical and current guidelines', 'Beneficiary families in eligible urban areas that do not own a pucca house in the name of the household or its members, subject to the active PMAY-U vertical, income category, and State/UT process.', 'You may qualify if your eligible urban household does not own a pucca house and meets the current income and vertical-specific rules.', 'Housing assistance under the active PMAY-U vertical, with the amount and form of support determined by the current operational guidelines and beneficiary category.', ARRAY['Identity proof', 'Address and urban-residence proof', 'Income or category proof', 'Household and ownership declaration', 'Bank details', 'Documents requested by the ULB or implementing agency']::text[], 'Through the official PMAY-U/ULB application or demand-survey process', 'https://pmay-urban.gov.in/', 'https://pmay-urban.gov.in/about', 'Subject to the active PMAY-U 2.0 guidelines and local-body process.', '2026-08-27', 'SchemeSetu source pass', 'The official page contains legacy PMAY-U vertical information; publish only after reconciling it with current PMAY-U 2.0 guidelines.'),
(55, 'pradhan-mantri-kisan-samman-nidhi', 'Pradhan Mantri Kisan Samman Nidhi', 'Department of Agriculture and Farmers Welfare, Ministry of Agriculture and Farmers Welfare', ARRAY['Agriculture', 'Farmers', 'Income Support']::text[], NULL, NULL, 'Eligible landholding farmer families as defined under the PM-KISAN guidelines, subject to State/UT identification and exclusion categories covering institutional landholders, certain public-office holders, specified government employees or pensioners, income-tax payers, and practicing professionals.', 'You may qualify if your family holds eligible agricultural land and does not fall within the official exclusion categories.', '₹6,000 per year in three equal installments through direct bank transfer.', ARRAY['Aadhaar or accepted identity record', 'Landholding and farmer records', 'Bank account details', 'eKYC', 'State/UT registration information']::text[], 'Online through the official PM-KISAN portal, mobile app, or prescribed assisted/state channel', 'https://pmkisan.gov.in/', 'https://pmkisan.gov.in/', 'Registration and status services remain subject to portal and State/UT processes.', '2026-08-27', 'SchemeSetu source pass', 'Portal currently states eKYC is mandatory and displays current installment information; always check Know Your Status and latest exclusions.'),
(56, 'pradhan-mantri-fasal-bima-yojana', 'Pradhan Mantri Fasal Bima Yojana', 'Ministry of Agriculture and Farmers Welfare', ARRAY['Agriculture', 'Crop Insurance', 'Farmers']::text[], NULL, NULL, 'Farmers in notified areas and crops may enroll under the applicable PMFBY operational guidelines and State/season notification.', 'You may qualify if you grow a notified crop in a notified area during the applicable season and meet the current enrollment rules.', 'Crop-insurance protection under the applicable season, crop, State, premium, and loss-assessment rules, with policy status and grievance/crop-loss reporting services.', ARRAY['Farmer identity and land/cultivation record', 'Bank account details', 'Crop and season details', 'Lease or cultivation proof where applicable', 'Policy or application ID']::text[], 'Online through the official PMFBY portal or authorized bank/insurance/CSC channel', 'https://pmfby.gov.in/', 'https://pmfby.gov.in/', 'State- and season-specific enrollment deadlines apply.', '2026-08-27', 'SchemeSetu source pass', 'Premium, crop, area, cutoff, and loss-reporting rules must be read from the current operational guideline and State notification.'),
(57, 'ayushman-bharat-pm-jay', 'Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana', 'National Health Authority, Ministry of Health and Family Welfare', ARRAY['Health', 'Hospitalization', 'Insurance']::text[], NULL, 'Eligibility is determined through the applicable beneficiary database and current PM-JAY rules; do not infer it from income alone.', 'Beneficiary eligibility follows the current National Health Authority and State/UT implementation rules and beneficiary identification process.', 'You may qualify if you are included in the applicable PM-JAY beneficiary database or current expansion category and can complete the official verification process.', 'Cashless health-service access at empanelled facilities under the current PM-JAY package and beneficiary rules; verify the current coverage and state-specific implementation on the NHA portal.', ARRAY['Aadhaar or accepted identity document', 'Beneficiary or family identification details', 'State/UT verification records', 'Documents requested by the empanelled facility']::text[], 'Beneficiary verification and card services through official PM-JAY/NHA channels, empanelled hospitals, and State/UT systems', 'https://www.pmjay.gov.in/', 'https://www.pmjay.gov.in/', 'Beneficiary services are subject to current NHA and State/UT processes.', '2026-08-27', 'SchemeSetu source pass', 'The NHA portal warns that pmjay.gov.in is the only official PM-JAY website; do not publish an income-only rule or a fixed benefit figure without the current scheme documentation.'),
(58, 'pradhan-mantri-matsya-sampada-yojana', 'Pradhan Mantri Matsya Sampada Yojana', 'Department of Fisheries, Ministry of Fisheries, Animal Husbandry and Dairying', ARRAY['Fisheries', 'Livelihoods', 'Agriculture', 'Blue Economy']::text[], NULL, NULL, 'Fisheries-sector beneficiaries and eligible entities under the applicable PMMSY component, State/UT plan, and current operational guidelines.', 'You may qualify if you are a fisher, fish farmer, fisheries worker, entrepreneur, or eligible fisheries entity under an active State/UT component.', 'Support for sustainable and responsible fisheries-sector development under the applicable component and approved plan.', ARRAY['Identity and address proof', 'Fisher/fish-farmer or enterprise details', 'Bank account details', 'Project or activity documents', 'State/UT fisheries registration where required']::text[], 'Through the Department of Fisheries and the prescribed State/UT fisheries implementation channel', 'https://pmmsy.dof.gov.in/', 'https://pmmsy.dof.gov.in/', 'Component and State/UT implementation windows apply.', '2026-08-27', 'SchemeSetu source pass', 'The official page states an FY 2020-21 to FY 2024-25 implementation period; confirm current continuation and active application window before publishing.'),
(59, 'pradhan-mantri-shram-yogi-maandhan', 'Pradhan Mantri Shram Yogi Maan-Dhan Yojana', 'Ministry of Labour and Employment', ARRAY['Pension', 'Unorganised Workers', 'Social Security']::text[], NULL, 'Monthly income below ₹15,000', 'Indian unorganised workers aged 18–40 who are not members of EPFO, ESIC, or a government-funded NPS and meet the current enrolment conditions.', 'You may qualify if you are an unorganised worker aged 18–40, earn below the current income limit, and are not covered by the excluded pension or social-security systems.', 'Voluntary contributory pension with a government matching contribution; the official summary states an assured pension of ₹3,000 per month after age 60 and a spouse benefit under scheme rules.', ARRAY['Aadhaar', 'Savings bank or Jan-Dhan account', 'Mobile number', 'Occupation and income details', 'Consent for contribution auto-debit']::text[], 'Online through the official Maandhan portal or prescribed assisted channel', 'https://maandhan.in/maandhan/login', 'https://eshram.gov.in/social-security-welfare-schemes', 'Open subject to the current Maandhan enrolment process.', '2026-08-28', 'SchemeSetu source pass', 'Confirm current contribution chart and exit/claim rules on the official Maandhan portal.'),
(60, 'national-pension-scheme-traders-self-employed', 'National Pension Scheme for Traders and the Self-employed Persons', 'Ministry of Labour and Employment', ARRAY['Pension', 'Traders', 'Self Employment', 'Social Security']::text[], NULL, 'Annual turnover not more than ₹1.5 crore', 'Indian shopkeepers or owners of eligible petty or small shops, restaurants, hotels, or similar businesses aged 18–40, not covered by EPFO, ESIC, or PM-SYM, and within the current turnover condition.', 'You may qualify if you are an eligible small trader or self-employed person aged 18–40 and meet the turnover and social-security conditions.', 'Voluntary contributory pension with central-government matching; the official summary states an assured pension of ₹3,000 per month after age 60.', ARRAY['Aadhaar', 'Savings bank or Jan-Dhan account', 'Mobile number', 'Business and turnover details', 'Consent for contribution auto-debit']::text[], 'Online through the official Maandhan channel or prescribed assisted channel', 'https://maandhan.in/maandhan/login', 'https://eshram.gov.in/social-security-welfare-schemes', 'Open subject to the current Maandhan enrolment process.', '2026-08-28', 'SchemeSetu source pass', 'Confirm current contribution chart and business-category rules on the official portal.'),
(61, 'pradhan-mantri-suraksha-bima-yojana', 'Pradhan Mantri Suraksha Bima Yojana', 'Department of Financial Services, Ministry of Finance', ARRAY['Insurance', 'Accident Protection', 'Social Security']::text[], NULL, NULL, 'Indian citizens aged 18–70 with a Jan-Dhan or savings bank account linked as required, and consent for auto-debit under the scheme.', 'You may qualify if you are 18–70 and hold an eligible bank account that can be enrolled through consent-based auto-debit.', '₹2 lakh for accidental death or full disability and ₹1 lakh for partial disability under the current summary terms.', ARRAY['Savings bank or Jan-Dhan account', 'Aadhaar or bank KYC', 'Consent-cum-declaration', 'Nominee details']::text[], 'Through a participating bank or official Jan Suraksha channel', 'https://jansuraksha.gov.in/Forms-PMSBY.aspx', 'https://eshram.gov.in/social-security-welfare-schemes', 'Annual enrollment/renewal cycle as communicated by the participating bank.', '2026-08-28', 'SchemeSetu source pass', 'Confirm the current premium, coverage exclusions, and renewal date from the latest official rules.'),
(62, 'atal-pension-yojana', 'Atal Pension Yojana', 'Department of Financial Services, Ministry of Finance', ARRAY['Pension', 'Financial Security', 'Social Security']::text[], NULL, NULL, 'Indian citizens aged 18–40 with an eligible bank account linked as required under the current APY rules.', 'You may qualify if you are 18–40, are an Indian citizen, and can contribute through an eligible bank account.', 'Choice of a pension level from ₹1,000 to ₹5,000 under the current scheme structure, with spouse and nominee provisions under the rules.', ARRAY['Aadhaar or bank KYC', 'Savings bank account', 'Mobile number', 'Nominee and spouse details', 'Contribution mandate']::text[], 'Through a participating bank or official APY channel', 'https://www.npscra.nsdl.co.in/nsdl-forms.php', 'https://eshram.gov.in/social-security-welfare-schemes', 'Open subject to bank enrollment and current APY rules.', '2026-08-28', 'SchemeSetu source pass', 'Confirm current contribution schedule and tax/eligibility rules before presenting a personalized recommendation.'),
(63, 'public-distribution-system-nfsa-onorc', 'Public Distribution System under NFSA and ONORC', 'Department of Food and Public Distribution, Ministry of Consumer Affairs, Food and Public Distribution', ARRAY['Food Security', 'Nutrition', 'Migrant Support']::text[], NULL, 'State/UT NFSA eligibility rules apply', 'Eligible households identified under the applicable National Food Security Act and State/UT ration-card rules; ONORC supports portability for eligible beneficiaries.', 'You may qualify if your household is covered by the applicable NFSA and State/UT food-security entitlement.', 'Subsidized or entitled food grains under the applicable ration-card category and portability through One Nation One Ration Card where enabled.', ARRAY['Ration-card application or ration card', 'Identity and address proof', 'Household details', 'Aadhaar where required by the State/UT process']::text[], 'Through the State/UT food and civil-supplies department or official NFSA channel', 'https://nfsa.gov.in/portal/PDS_page', 'https://eshram.gov.in/social-security-welfare-schemes', 'State/UT application and verification timelines apply.', '2026-08-28', 'SchemeSetu source pass', 'Entitlement quantity and eligibility are State/UT and category dependent; never display a single nationwide quantity as universal.'),
(64, 'national-social-assistance-programme-old-age', 'National Social Assistance Programme - Old Age Support', 'Ministry of Rural Development', ARRAY['Pension', 'Senior Citizens', 'Social Assistance']::text[], NULL, 'State/UT and NSAP poverty/eligibility criteria apply', 'Eligible Indian senior citizens with little or no regular means of subsistence under the applicable NSAP and State/UT rules.', 'You may qualify if you are an eligible older person without sufficient regular means of support and meet the current State/UT verification rules.', 'Central assistance combined with applicable State contribution; amount and age bands vary under current NSAP and State/UT rules.', ARRAY['Age proof', 'Identity proof', 'Residence proof', 'Bank or post-office account', 'Income or means-related declaration']::text[], 'Through the official State/UT social-welfare or NSAP channel', 'https://nsap.nic.in/', 'https://eshram.gov.in/social-security-welfare-schemes', 'State/UT application and verification timelines apply.', '2026-08-28', 'SchemeSetu source pass', 'Pension amount and eligibility age/category must be displayed from the current State/UT and NSAP rules.'),
(65, 'pradhan-mantri-kisan-maandhan-yojana', 'Pradhan Mantri Kisan Maandhan Yojana', 'Ministry of Agriculture and Farmers Welfare', ARRAY['Agriculture', 'Pension', 'Small Farmers']::text[], NULL, NULL, 'Small and marginal farmers aged 18–40 with cultivable land up to 2 hectares as recorded by the relevant State/UT land records, subject to current exclusions.', 'You may qualify if you are a small or marginal farmer aged 18–40 with eligible landholding and meet the current pension-scheme conditions.', 'Voluntary contributory pension with government matching contribution and an assured pension of ₹3,000 per month after age 60 under the current summary.', ARRAY['Aadhaar', 'Bank account', 'Landholding record', 'Mobile number', 'Contribution mandate']::text[], 'Through the official PM-KMY portal or prescribed assisted channel', 'https://pmkmy.gov.in/', 'https://eshram.gov.in/social-security-welfare-schemes', 'Open subject to current PM-KMY enrollment and State/UT land-record verification.', '2026-08-28', 'SchemeSetu source pass', 'Confirm current exclusions, contribution schedule, and application availability on PM-KMY before publication.'),
(66, 'self-employment-scheme-rehabilitation-manual-scavengers', 'Self-Employment Scheme for Rehabilitation of Manual Scavengers', 'Ministry of Social Justice and Empowerment', ARRAY['Social Justice', 'Livelihoods', 'Rehabilitation']::text[], NULL, NULL, 'Identified manual scavengers, one from each eligible family, under the applicable rehabilitation and identification rules.', 'You may qualify if you are an officially identified manual scavenger or eligible dependent under the current rehabilitation process.', 'One-time cash assistance subject to current rules, free skill training, and a stated monthly training stipend, with amounts subject to revision by the implementing authority.', ARRAY['Identity proof', 'Official identification or survey record', 'Bank account', 'Family/dependent details', 'Training and rehabilitation documents']::text[], 'Through the official NSKFDC or State implementing channel', 'https://nskfdc.nic.in/', 'https://eshram.gov.in/social-security-welfare-schemes', 'Subject to identification and current State/NSKFDC implementation process.', '2026-08-28', 'SchemeSetu source pass', 'Cash-assistance and stipend amounts require confirmation from the latest NSKFDC operational documents before publication.'),
(67, 'pm-vishwakarma', 'PM Vishwakarma', 'Ministry of Micro, Small and Medium Enterprises', ARRAY['Artisans', 'Livelihoods', 'Skill Development', 'Enterprise']::text[], NULL, NULL, 'An artisan or craftsperson aged at least 18, working with hands and tools in one of the 18 listed family-based traditional trades on a self-employment basis; one member per family; government employees and their family members are excluded; prior similar credit restrictions apply.', 'You may qualify if you are at least 18 and earn through one of the listed traditional trades, while meeting the family, government-service, and prior-loan conditions.', 'Recognition certificate and ID card, skill training, ₹500 per day training stipend, toolkit incentive up to ₹15,000, collateral-free credit support, digital-transaction incentive, and marketing support.', ARRAY['Aadhaar', 'Mobile number', 'Bank details', 'Ration card or Aadhaar details of all family members where a ration card is unavailable', 'Trade and registration information']::text[], 'Online through the official PM Vishwakarma portal, generally with CSC assistance', 'https://pmvishwakarma.gov.in/', 'https://pmvishwakarma.gov.in/Home/FAQ', 'Open subject to portal and current scheme availability.', '2026-08-28', 'SchemeSetu source pass', 'The official FAQ lists 18 trades and current loan/training terms; confirm current component availability before recommending credit.'),
(68, 'indira-gandhi-national-disability-pension-scheme', 'Indira Gandhi National Disability Pension Scheme', 'Ministry of Rural Development, National Social Assistance Programme', ARRAY['Disability', 'Pension', 'Social Assistance']::text[], NULL, 'Below Poverty Line under applicable norms', 'Indian residents aged 18 or above with a qualifying severe disability under the current disability-certification and BPL rules; the captured page states 80% or more disability.', 'You may qualify if you are an eligible adult with a qualifying disability and belong to a BPL household under the current NSAP rules.', 'The captured official record states ₹300 per month for beneficiaries aged 18–79 and ₹500 per month for beneficiaries aged 80 and above, subject to current central and State/UT contributions.', ARRAY['BPL card or applicable poverty-status proof', 'Aadhaar', 'Age proof', 'Disability certificate from the competent medical authority', 'Passport-size photographs', 'Bank or post-office account']::text[], 'Online through UMANG or the official NSAP portal, and through prescribed State/UT/local-body channels', 'https://nsap.nic.in/', 'https://www.myscheme.gov.in/schemes/igndps', 'State/UT application and verification timelines apply.', '2026-08-28', 'SchemeSetu source pass', 'Use the current NSAP guideline PDF linked on the official detail page for final disability threshold, pension amount, and State/UT rules.'),
(69, 'pm-street-vendor-atmanirbhar-nidhi', 'PM Street Vendor''s AtmaNirbhar Nidhi', 'Ministry of Housing and Urban Affairs', ARRAY['Street Vendors', 'Livelihoods', 'Working Capital', 'Urban Support']::text[], NULL, NULL, 'Street vendors holding a Certificate of Vending or Identity Card; identified vendors without those documents; or vendors with an official Letter of Recommendation from the ULB/Town Vending Committee, including eligible peri-urban or rural vendors operating within ULB limits.', 'You may qualify if you are a street vendor with a vending identity document or an official ULB/TVC recommendation.', 'Working-capital loans in successive tranches up to ₹15,000, ₹25,000, and ₹50,000, 7% interest subsidy under current terms, digital-transaction cashback, credit-guarantee support, and a possible UPI-linked RuPay credit card after qualifying repayment.', ARRAY['Certificate of Vending or Identity Card', 'ULB/TVC Letter of Recommendation where applicable', 'Aadhaar', 'Voter ID, driving licence, MGNREGA card, or PAN for KYC', 'Bank account/passbook', 'Loan-closure document for a later tranche where applicable']::text[], 'Online through the official PM SVANidhi portal or through the prescribed ULB/assisted channel', 'https://pmsvanidhi.mohua.gov.in/', 'https://www.myscheme.gov.in/schemes/pm-svanidhi', 'Subject to current PM SVANidhi portal and lender availability.', '2026-08-28', 'SchemeSetu source pass', 'The official detail page states current tranche, interest-subsidy, cashback, and credit-card terms; show the lender/portal confirmation before application.'),
(70, 'prime-ministers-employment-generation-programme', 'Prime Minister''s Employment Generation Programme', 'Ministry of Micro, Small and Medium Enterprises', ARRAY['Employment', 'Entrepreneurship', 'Micro Enterprises', 'Livelihoods']::text[], NULL, NULL, 'Individuals above 18 years may apply for eligible new micro-enterprises; for projects above the stated thresholds, at least VIII-standard qualification is required. Existing units and units already receiving government subsidy are excluded under the published rules.', 'You may qualify if you are an adult setting up an eligible new micro-enterprise and meet the project, contribution, category, and activity rules.', 'Credit-linked margin-money subsidy for eligible new micro-enterprises, with different own-contribution and subsidy rates for general and special categories and higher support in rural areas under the published guidelines.', ARRAY['Identity and address proof', 'Caste or special-category certificate where applicable', 'Rural-area certificate where applicable', 'Project report', 'Education/EDP/skill certificate', 'Bank and enterprise documents']::text[], 'Online through the official KVIC PMEGP e-portal and participating implementing agencies/banks', 'https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp', 'https://www.myscheme.gov.in/schemes/pmegp', 'Current-cycle availability and annual allocations must be confirmed on the official KVIC portal.', '2026-08-28', 'SchemeSetu source pass', 'The official page states continuation through 2025-26; verify current cycle, project ceilings, subsidy, and eligible activities before publication.'),
(71, 'aicte-pragati-scholarship-degree', 'AICTE Pragati Scholarship Scheme for Girl Students (Degree)', 'All India Council for Technical Education', ARRAY['Education', 'Scholarship', 'Women', 'Technical Education']::text[], 'First-year degree or second-year degree through lateral entry in an AICTE-approved institution', 'Not more than ₹8,00,000 per annum', 'A girl student admitted to the first year of a degree course or second year through lateral entry in an AICTE-approved institution; maximum two girl children per family; family income not above ₹8 lakh per annum with a valid income certificate.', 'You may qualify if you are a girl student entering an eligible AICTE-approved degree course and your family income is within the current limit.', '₹50,000 per annum for each year of study, up to four years for first-year entrants or three years for lateral entrants, paid through DBT.', ARRAY['Admission and institute verification', 'Income certificate issued by the State/UT', 'Academic marksheet', 'Aadhaar and bank details', 'Category documents where applicable']::text[], 'Online through the National Scholarship Portal after the AICTE application notice', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/AICTE/AICTE_2010_G.pdf', 'Check the active NSP/AICTE cycle before applying.', '2026-08-28', 'SchemeSetu source pass', 'The guideline PDF is dated 2020-21; verify current AICTE cycle and amount before publication.'),
(72, 'aicte-saksham-scholarship-diploma', 'AICTE Saksham Scholarship Scheme for Specially-Abled Students (Diploma)', 'All India Council for Technical Education', ARRAY['Education', 'Scholarship', 'Disability', 'Technical Education']::text[], 'First-year diploma or second-year diploma through lateral entry in an AICTE-approved institution', 'Not more than ₹8,00,000 per annum', 'A student with at least 40% disability admitted to the first year of a diploma course or second year through lateral entry in an AICTE-approved institution; current family-income certification is required.', 'You may qualify if you have at least 40% disability, are entering an eligible AICTE-approved diploma course, and meet the income limit.', '₹50,000 per annum for each year of study, up to three years for first-year entrants or two years for lateral entrants, paid through DBT.', ARRAY['Disability certificate', 'Income certificate issued by the State/UT', 'Admission and institute verification', 'Academic marksheet', 'Aadhaar and bank details']::text[], 'Online through the National Scholarship Portal after the AICTE application notice', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/AICTE/AICTE_2013_G.pdf', 'Check the active NSP/AICTE cycle before applying.', '2026-08-28', 'SchemeSetu source pass', 'The guideline PDF is dated 2020-21; verify current AICTE cycle and amount before publication.'),
(73, 'pm-yasasvi-top-class-college-obc-ebc-dnt', 'PM YASASVI Central Sector Scheme of Top Class Education in College for OBC, EBC and DNT Students', 'Department of Social Justice and Empowerment', ARRAY['Education', 'Scholarship', 'OBC', 'EBC', 'DNT']::text[], 'Full-time prescribed course beyond Class XII in a notified top-class institution', 'Total annual family income up to ₹2,50,000', 'OBC, EBC, or DNT students with annual family income up to ₹2.5 lakh who secure admission to a full-time prescribed course in a notified institution, subject to available slots, merit, sibling limits, and current rules.', 'You may qualify if you belong to OBC, EBC, or DNT categories, meet the income limit, and have admission to a notified top-class institution.', 'Full tuition and non-refundable charges within the scheme ceilings, ₹3,000 per month living expenses, ₹5,000 per year for books and stationery, and one-time computer/laptop assistance up to ₹45,000 under the guideline.', ARRAY['Income certificate', 'Caste/category certificate', 'Admission and rank details', 'Fee details', 'Aadhaar and bank account', 'Sibling affidavit where required']::text[], 'Online through the National Scholarship Portal with institution verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/ApprovedmodifieddraftofTopClassCollege.pdf', 'Check the current NSP cycle and notified-institution list before applying.', '2026-08-28', 'SchemeSetu source pass', 'Slots and notified institutions can change by financial year; display the current list and current NSP dates.'),
(74, 'sukanya-samriddhi-account-scheme', 'Sukanya Samriddhi Account Scheme', 'National Savings Institute, Ministry of Finance', ARRAY['Women', 'Children', 'Savings', 'Education']::text[], NULL, NULL, 'An account may be opened in the name of a girl child until she attains 10 years of age; one account is permitted per girl child under the scheme rules.', 'A parent or guardian can open this government savings account for an eligible girl child before her tenth birthday.', 'Government small-savings account with deposits from ₹250 to ₹1.5 lakh per financial year, education-withdrawal provisions, transferability across India, 21-year maturity, and tax treatment under applicable law.', ARRAY['Girl child''s birth certificate', 'Parent/guardian identity and KYC documents', 'Residence/address proof', 'Account-opening form']::text[], 'Open through a post office or authorised bank using the official form and KYC process', 'https://www.nsiindia.gov.in/InternalPage.aspx?Id_Pk=38', 'https://www.nsiindia.gov.in/InternalPage.aspx?Id_Pk=89', 'Account opening is subject to the scheme rules and authorised-bank/post-office service availability.', '2026-08-28', 'SchemeSetu source pass', 'This is a savings account scheme, not an automatic cash-benefit grant; interest rates and tax rules should be checked against current official notifications.'),
(75, 'pm-cares-for-children', 'PM CARES for Children Scheme', 'Ministry of Women and Child Development', ARRAY['Children', 'Health', 'Education', 'Social Security']::text[], 'School and higher education support for eligible beneficiaries', NULL, 'Children who lost both parents, a surviving parent, or legal/adoptive parents to the COVID-19 pandemic between 11 March 2020 and 5 May 2023, and who had not completed 18 years on the date of the parents'' death, subject to official beneficiary identification.', 'This is for children officially identified as having lost eligible parents or guardians to COVID-19 while they were under 18.', 'The official FAQ lists health insurance, school and higher-education support, ₹20,000 annual school scholarship, ₹4,000 monthly Mission Vatsalya support where applicable, education-loan interest subsidy, and a corpus designed to reach ₹10 lakh with payment at age 23 under the scheme rules.', ARRAY['Proof of death and COVID-period eligibility', 'Child''s birth and identity records', 'Caregiver or legal-guardian records', 'PM CARES beneficiary certificate/ID where issued', 'Bank and education records where applicable']::text[], 'Through the official PM CARES for Children portal, caregiver/agency, or Child Welfare Committee channel for beneficiary identification', 'https://pmcaresforchildren.in/', 'https://www.spniwcd.wcd.gov.in/pm-cares-for-children-scheme/faqs', 'Enrollment eligibility is tied to the published COVID-period criteria and official beneficiary identification.', '2026-08-28', 'SchemeSetu source pass', 'Display only for officially identified beneficiaries; do not present it as an open general application scheme.'),
(76, 'mission-vatsalya-child-protection', 'Mission Vatsalya (Child Protection Services and Child Welfare Services)', 'Ministry of Women and Child Development', ARRAY['Children', 'Child Protection', 'Foster Care', 'Social Support']::text[], NULL, 'Caregiver family income below ₹8,00,000 per annum or current Ministry rule', 'Children below 18 may qualify for sponsorship, foster care, or adoption-related services; after-care can support young people leaving Child Care Institutions from age 18 up to 21, extendable to 23, subject to State/UT and district procedures.', 'Children needing care or protection and eligible foster, caregiver, or after-care applicants may receive support through the State and district child-protection system.', 'Family-based sponsorship and foster-care support, adoption facilitation, after-care assistance, and a ₹4,000 monthly grant to States under sponsorship, foster care, or after-care components, subject to applicable approval.', ARRAY['Birth certificate', 'Aadhaar or identity record', 'School-going certificate where applicable', 'Vaccination and health records', 'Child Welfare Committee, foster, adoption, or special-needs records where applicable']::text[], 'Through State/UT Women and Child Development departments, District Child Protection Units, Child Welfare Committees, or prescribed child-protection channels', 'https://missionvatsalya.wcd.gov.in/', 'https://www.myscheme.gov.in/schemes/mvcppsacws', 'State/UT and district procedures apply; this is not a single national self-service application form.', '2026-08-28', 'SchemeSetu source pass', 'Eligibility, income thresholds, and approval routes can vary by State/UT implementation.'),
(77, 'free-coaching-sc-obc-pm-cares', 'Free Coaching for SCs, OBCs and Beneficiaries of PM CARES Children Scheme', 'Department of Social Justice and Empowerment', ARRAY['Education', 'Coaching', 'SC', 'OBC', 'PM CARES']::text[], 'Class XII or undergraduate-level qualifying stage depending on the competitive examination', 'Up to ₹8,00,000 per annum for SC/OBC applicants; no caste or income restriction for eligible PM CARES beneficiaries', 'SC or OBC students meeting the income and qualifying-exam conditions, or officially certified PM CARES beneficiaries; benefits are limited by the scheme''s repeat-use, marks, and non-duplication rules.', 'You may qualify if you are an eligible SC/OBC student or PM CARES beneficiary preparing for a listed competitive examination and are not already using another coaching scheme.', '₹4,000 per month stipend for up to 12 months, interview incentive up to ₹15,000 for specified examinations, course-fee support within published ceilings, and DBT payment.', ARRAY['Photograph', 'Aadhaar', 'Income certificate where required', 'Caste certificate where required', 'Residence and age proof', 'Academic marksheets', 'Aadhaar-linked bank details', 'PM CARES beneficiary certificate where applicable', 'Non-duplication declarations']::text[], 'Online through notifications issued by empanelled Central Universities', 'https://socialjustice.gov.in/schemes/108', 'https://www.myscheme.gov.in/schemes/fcssos', 'Depends on current advertisements from empanelled Central Universities.', '2026-08-28', 'SchemeSetu source pass', 'The current university notification and empanelment list must be checked before directing an applicant.'),
(78, 'aicte-swanath-scholarship', 'AICTE Swanath Scholarship Scheme', 'All India Council for Technical Education', ARRAY['Education', 'Scholarship', 'Orphans', 'Armed Forces', 'Disaster-Affected Families']::text[], 'Regular degree or diploma study in an AICTE-approved institution', 'Not more than ₹8,00,000 per annum', 'Students who are orphans, lost one or both parents to COVID-19, are wards of Armed Forces or Central Paramilitary Forces personnel martyred in action, or have a parent with critical disease or severe accident disability above 80%, provided they meet the income, AICTE-approved regular-course, and non-duplication conditions.', 'You may qualify if you are in one of the scheme''s protected family circumstances, study a regular AICTE-approved degree or diploma, meet the income limit, and do not receive another government scholarship.', '₹50,000 per annum for each year of study, up to four years for first-year degree entrants and three years for diploma students, paid through DBT.', ARRAY['Death certificates or competent-authority orphan certificate where applicable', 'COVID death certificate where applicable', 'Shaheed certificate for eligible Armed Forces/Paramilitary wards', 'Critical-disease or disability proof where applicable', 'Income certificate', 'Bonafide certificate', 'Academic marksheets', 'Aadhaar and bank details', 'Category certificate where applicable']::text[], 'Online through the National Scholarship Portal after AICTE/NSP notification, with institute and State/UT verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/AICTE/AICTE_3039_G.pdf', 'Check the active NSP/AICTE cycle before applying.', '2026-08-28', 'SchemeSetu source pass', 'The guideline is dated May 2025; current cycle, slots, and any operational changes should be checked on NSP.'),
(79, 'scholarships-for-students-with-disabilities', 'Central Sector Umbrella Scheme of Scholarships for Students with Disabilities', 'Department of Empowerment of Persons with Disabilities, Ministry of Social Justice and Empowerment', ARRAY['Education', 'Scholarship', 'Disability', 'Accessibility']::text[], 'Pre-matric, post-matric, top-class, overseas, fellowship, and free-coaching components under current guidelines', '₹2,50,000 for pre-matric/post-matric; ₹8,00,000 for top-class, overseas, and free-coaching components; no income ceiling for National Fellowship under the captured guideline', 'Indian nationals with benchmark disability of at least 40% and a valid competent-authority disability certificate, Aadhaar-based authentication and UDID/UDID enrollment, subject to the component''s course, income, slot, and no-duplicate-scholarship conditions.', 'You may qualify if you are an Indian student with at least 40% benchmark disability, the required certificate/UDID information, and the income and course conditions for the component you choose.', 'Component-based support including pre-matric and post-matric scholarships, top-class education, overseas scholarship, national fellowship, and free coaching. The 2024 guideline includes maintenance, disability, book, tuition, and other allowances depending on component and course.', ARRAY['Disability certificate', 'UDID or UDID enrolment', 'Aadhaar/biometric authentication', 'Income certificate', 'Academic marksheets', 'Tuition-fee receipt', 'Bank passbook/cancelled cheque', 'Institute and course records', 'Computer or assistive-device purchase proof for relevant top-class claims']::text[], 'Online through the National Scholarship Portal for the pre-matric, post-matric, and top-class components; other components follow the current Department/portal process', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/DEPDGuidelines_1.pdf', 'Opening and closing dates are set for the active NSP cycle; slots and notified institutions apply.', '2026-08-28', 'SchemeSetu source pass', 'This is an umbrella record; the UI should direct users to the correct component and show component-specific amounts and eligibility rather than implying one universal benefit.'),
(80, 'national-scholarship-higher-education-students', 'National Scholarship for Higher Education of Scheduled Tribe Students', 'Ministry of Tribal Affairs', ARRAY['Education', 'Scholarship', 'ST', 'Higher Education']::text[], 'Graduate and postgraduate courses in Ministry-notified premier institutions', 'Up to ₹6,00,000 per annum; income rule does not apply to an orphan supported by a guardian under the captured guideline', 'ST students admitted on merit to courses and institutions notified by the Ministry of Tribal Affairs, subject to the income, no-duplicate-scholarship, and institution/course rules.', 'You may qualify if you are an ST student admitted on merit to a Ministry-notified premier institution and meet the current income and course conditions.', 'Full scholarship support under the scheme, including tuition/admission fees subject to government or private-institution ceilings, ₹5,000 per year for books and stationery, ₹3,000 monthly stipend, and one-time computer/accessories support up to ₹45,000.', ARRAY['ST or PVTG certificate', 'Income certificate', 'Fee receipt', 'Bank passbook', 'Qualifying-exam marksheet', 'Bona fide certificate from institution']::text[], 'Online through the National Scholarship Portal after the annual Ministry/NSP window opens', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/tribalfellowshipguideline.pdf', 'Annual NSP dates and notified institution list must be checked for the active cycle.', '2026-08-28', 'SchemeSetu source pass', 'The captured guideline covers 2021-22 to 2025-26; current cycle provisions should be checked before application.'),
(81, 'national-scholarship-postgraduate-studies', 'National Scholarship for Postgraduate Studies', 'University Grants Commission, Ministry of Education', ARRAY['Education', 'Scholarship', 'Postgraduate', 'Women']::text[], 'First regular/full-time postgraduate degree', NULL, 'Indian students admitted in the first year of a first postgraduate degree programme, below 30 years at admission, in an eligible recognized institution and regular/full-time programme; open/distance, correspondence, private, and part-time modes are excluded.', 'You may qualify if you are below 30, newly admitted to your first regular postgraduate degree in an eligible institution, and are not taking another scholarship or paid benefit during the award.', '₹15,000 per month for 10 months each year for two years, subject to the approved number of awards and merit/reservation rules; 30% slots are reserved for women, with special treatment for eligible single/twin/fraternal girl children under the guideline.', ARRAY['UG degree/marksheet', 'Admission and bonafide certificate', 'Institution verification certificate', 'Category certificate where applicable', 'Aadhaar-linked bank account details']::text[], 'Online through the National Scholarship Portal with institution verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/Guidelines_NATIONAL_SCHOLARSHIP_FOR_POSTGRADUATE_STUDIES_UGC_2324.pdf', 'Annual NSP application and institution-verification dates apply.', '2026-08-28', 'SchemeSetu source pass', 'The captured guideline is labelled 2021 and the current UGC/NSP cycle must be checked before showing the award as open.'),
(82, 'pmss-rpf-rpsf-wards', 'Prime Minister''s Scholarship Scheme for Wards of RPF/RPSF', 'Security Directorate, Ministry of Railways', ARRAY['Education', 'Scholarship', 'Railways', 'Professional Courses']::text[], 'Regular professional and technical degree courses, subject to the notified course list', NULL, 'Eligible wards or widows of serving, retired, or deceased RPF/RPSF personnel who take regular admission in a notified professional/technical course and secure at least 60% in the minimum entry qualification, subject to quota and preference rules.', 'You may qualify if you are an eligible RPF/RPSF ward or widow entering a recognized professional or technical course with at least 60% in the required qualifying examination.', '₹2,500 per month for male students and ₹3,000 per month for female students for two to five years depending on course duration, paid through PFMS/DBT.', ARRAY['Service certificate for serving personnel category', 'PPO/discharge book for eligible retired/deceased categories', 'Qualifying-exam marksheet', 'Admission/course proof', 'Aadhaar-seeded bank account details', 'Institute verification records']::text[], 'Online through the National Scholarship Portal with institute and Railways/RPF verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/MORB_GL.pdf', 'Check the current NSP and Railway Board cycle; the captured guideline is for 2022-23 onwards.', '2026-08-28', 'SchemeSetu source pass', 'The scheme has a limited annual quota and category preference order; do not imply universal availability to all railway employees'' children.'),
(83, 'top-class-scholarship-sc-students', 'Top Class Scholarship for SC Students', 'Department of Social Justice and Empowerment, Ministry of Social Justice and Empowerment', ARRAY['Education', 'Scholarship', 'SC', 'Higher Education']::text[], 'Full-time courses beyond Class XII in notified top-class institutions', 'Up to ₹8,00,000 per annum', 'SC students with family income up to ₹8 lakh who secure admission in a full-time prescribed course in a Ministry-notified institution, selected within the institution''s allocated slots and subject to merit and renewal conditions.', 'You may qualify if you are an SC student with family income within ₹8 lakh, admitted full-time to a notified top institution, and selected within that institution''s available slots.', 'Full tuition and non-refundable charges, with a private-institution ceiling of ₹2 lakh per year, plus academic allowance of ₹86,000 in the first year and ₹41,000 in later years, paid through DBT.', ARRAY['SC certificate', 'Income certificate', 'Admission rank/merit details', 'Fee details', 'Bank account details', 'Institute verification']::text[], 'Online through the National Scholarship Portal with institute verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/Top_Class_Education_Scheme_2018.pdf', 'Check the active NSP cycle and current notified-institution list.', '2026-08-28', 'SchemeSetu source pass', 'Guideline states applicability from 2025-26; slots and notified institutions are decisive, so do not present this as universally available.'),
(84, 'top-class-college-education-obc-ebc-dnt', 'Top Class Education in College for OBC, EBC and DNT Students', 'Department of Social Justice and Empowerment, Ministry of Social Justice and Empowerment', ARRAY['Education', 'Scholarship', 'OBC', 'EBC', 'DNT', 'Higher Education']::text[], 'Full-time courses beyond Class XII in notified top-class institutions', 'Up to ₹2,50,000 per annum', 'OBC, EBC or DNT students with family income up to ₹2.5 lakh who secure admission in a full-time prescribed course in a Ministry-notified institution, subject to slots, merit, and renewal conditions.', 'You may qualify if you belong to OBC, EBC or DNT, meet the ₹2.5 lakh income limit, and have full-time admission in a notified institution.', 'Full tuition and non-refundable charges within notified ceilings, ₹3,000 per month living expenses, ₹5,000 per year for books and stationery, and one-time computer/accessories support up to ₹45,000, paid through DBT.', ARRAY['Caste/category certificate', 'Income certificate', 'Admission rank/merit details', 'Fee details', 'Bank account details', 'Institute verification']::text[], 'Online through the National Scholarship Portal with institute verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/ApprovedmodifieddraftofTopClassCollege.pdf', 'Check the active NSP cycle and current notified-institution list.', '2026-08-28', 'SchemeSetu source pass', 'The guideline gives a ₹2 lakh private-sector tuition ceiling and a higher ₹3.72 lakh ceiling for eligible flying-club courses; current institutional slots must be checked.'),
(85, 'post-matric-scholarship-obc-ebc-dnt', 'Post-Matric Scholarship for OBC, EBC and DNT Students', 'Department of Social Justice and Empowerment with State/UT Governments', ARRAY['Education', 'Scholarship', 'OBC', 'EBC', 'DNT', 'Post-Matric']::text[], 'Post-matric and post-secondary courses in recognized institutions in India', 'Up to ₹2,50,000 per annum for parent/guardian income under the captured guideline', 'Indian nationals belonging to OBC, EBC or DNT categories as notified for the State/UT to which they permanently belong, who have passed matriculation or a higher recognized examination and study eligible post-matric or post-secondary courses in recognized institutions.', 'You may qualify if you are an OBC, EBC or DNT student permanently belonging to the relevant State/UT, have passed Class X or higher, and meet the income and course rules.', 'State/UT-administered scholarship support covering applicable tuition and academic or other allowances under the notified group and rate schedule; eligible students may also use the freeship-card process where implemented.', ARRAY['OBC/EBC/DNT certificate', 'Income certificate', 'Matriculation or qualifying marksheet', 'Admission and fee records', 'Aadhaar-linked bank details', 'Institution verification']::text[], 'Through the National Scholarship Portal or the State/UT scholarship process, depending on the active implementation', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/POST_MATRIC_OBC_GUIDELINES.pdf', 'State/UT and NSP dates vary; check the applicant''s domicile authority.', '2026-08-28', 'SchemeSetu source pass', 'Benefit rates are administered and notified through States/UTs; the UI must request State before displaying exact amounts.'),
(86, 'nec-merit-scholarship', 'NEC Merit Scholarship for Students of North Eastern States', 'North Eastern Council, Ministry of Development of North Eastern Region', ARRAY['Education', 'Scholarship', 'North East', 'Higher Education']::text[], 'Recognized diploma, degree, postgraduate, M.Phil. and Ph.D. courses in India', 'Up to ₹8,00,000 per annum', 'Permanent residents of a North Eastern State admitted to a recognized diploma, degree, postgraduate, M.Phil. or Ph.D. course, with at least 60% in the relevant qualifying examination, within the prescribed course duration and without another scholarship or financial assistance.', 'You may qualify if you permanently live in a North Eastern State, have at least 60% in the relevant qualifying exam, and are studying an eligible recognized course without another scholarship.', 'Merit-based scholarship support for the prescribed course duration, disbursed by NEC through DBT at rates set by the current course-level schedule and notification.', ARRAY['Permanent Residential Certificate or Sikkim Certificate of Identification', 'Income certificate', 'Qualifying-exam marksheet', 'Bank account details', 'Admission/bonafide certificate', 'Research synopsis for M.Phil./Ph.D. where applicable']::text[], 'Online through the National Scholarship Portal with institute and domicile-State verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/NEC_1234_G.pdf', 'Annual announcement and NSP dates apply; confirm current rate schedule before application.', '2026-08-28', 'SchemeSetu source pass', 'Current benefit amount is intentionally not hard-coded because the captured guideline references a course-level schedule that should be checked against the live NEC notification.'),
(87, 'ishan-uday-special-scholarship', 'Ishan Uday Special Scholarship Scheme for North Eastern Region', 'University Grants Commission, Ministry of Education', ARRAY['Education', 'Scholarship', 'North East', 'Undergraduate']::text[], 'First regular/full-time undergraduate degree', 'Parental income below ₹4,50,000 per annum', 'Students who passed Class XII or equivalent from a school situated within the North Eastern Region, hold NER domicile, are admitted to the first year of a first regular/full-time UG degree in an eligible Indian institution, and are not admitted through management quota.', 'You may qualify if you studied Class XII in the North East, have NER domicile, are starting your first regular UG degree, and meet the income limit.', '₹8,000 per month for 10 months each year, for the prescribed UG course duration, subject to selection and renewal rules.', ARRAY['NER domicile certificate', 'Class XII marksheet', 'Income certificate', 'Admission/bonafide certificate', 'Aadhaar-linked bank details', 'Institution verification']::text[], 'Online through the National Scholarship Portal with institution verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/Guidelines_ISHAN%20UDAY_2324.pdf', 'Annual NSP application and verification dates apply.', '2026-08-28', 'SchemeSetu source pass', 'The captured guideline is labelled 2021/2023-24; confirm the current UGC/NSP cycle and institution accreditation conditions before showing as open.'),
(88, 'pmss-capf-assam-rifles', 'Prime Minister''s Scholarship Scheme for Wards and Widows of CAPF and Assam Rifles Personnel', 'Welfare and Rehabilitation Board, Ministry of Home Affairs', ARRAY['Education', 'Scholarship', 'CAPF', 'Assam Rifles', 'Professional Courses']::text[], 'Eligible higher technical and professional education', NULL, 'Dependent wards and widows of eligible Central Armed Police Forces and Assam Rifles personnel who satisfy the current service-category, course, merit, quota, and verification conditions under the PMSS guideline.', 'You may qualify if you are a dependent ward or widow covered by the CAPF/Assam Rifles categories and have admission to an eligible higher technical or professional course.', 'Scholarship support for the approved course duration under the current PMSS CAPF/Assam Rifles award schedule, disbursed through the official scholarship and DBT process.', ARRAY['Service/dependency certificate', 'Relevant service, death, discharge, or disability proof as applicable', 'Qualifying marksheet', 'Admission and course proof', 'Bank/Aadhaar details', 'Institute verification']::text[], 'Online through the National Scholarship Portal with institute and Welfare and Rehabilitation Board verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/warb/PMSS_Guidelines_1197_3001-2023-24.pdf', 'Check the active NSP/PMSS cycle before applying.', '2026-08-28', 'SchemeSetu source pass', 'The source PDF is large/image-heavy and current-cycle exact award amounts, quotas, and service categories must be rechecked from the live PMSS notice before publication.'),
(89, 'top-class-education-schools-obc-ebc-dnt', 'Top Class Education in Schools for OBC, EBC and DNT Students', 'Department of Social Justice and Empowerment, Ministry of Social Justice and Empowerment', ARRAY['Education', 'Scholarship', 'OBC', 'EBC', 'DNT', 'School']::text[], 'Classes IX to XII in identified Top Class Schools', 'Less than ₹2,50,000 per annum', 'OBC, EBC and DNT students studying in identified Top Class Schools, with household income below ₹2.5 lakh, selected through State-wise merit and available slots.', 'You may qualify if you belong to OBC, EBC or DNT, study in an identified Top Class School, and meet the income and merit rules.', 'Tuition, hostel and other eligible school charges up to ₹75,000 per year for Classes IX-X and ₹1,25,000 per year for Classes XI-XII, paid through DBT.', ARRAY['Category certificate', 'Income certificate', 'Previous-class marksheet', 'School verification', 'Bank account details']::text[], 'Online through the National Scholarship Portal with school and State verification', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/3061_G.pdf', 'Slots are announced annually; check the active NSP cycle and identified-school list.', '2026-08-28', 'SchemeSetu source pass', 'The guideline describes a central-sector component implemented with State assistance; exact current school list and dates must be checked.'),
(90, 'icar-jrf-pgs-agricultural-sciences', 'ICAR Junior Research Fellowship for Postgraduate Studies', 'Indian Council of Agricultural Research, Agricultural Education Division', ARRAY['Education', 'Fellowship', 'Agriculture', 'Postgraduate']::text[], 'Master''s degree in agricultural and allied sciences', NULL, 'Candidates with a relevant Bachelor''s degree or appearing in the final Bachelor''s examination, minimum qualifying marks/OGPA by category, and minimum age of 19, selected through the All India Competitive Examination and concurrent admission to eligible agricultural universities.', 'You may qualify if you have the relevant agricultural Bachelor''s degree, meet the category-wise marks requirement, are at least 19, and are selected through the ICAR examination and eligible university admission.', 'Fellowship and contingency support for a two-year Master''s programme at eligible agricultural universities, at rates prescribed by ICAR.', ARRAY['Bachelor''s degree or final-year proof', 'Marks/OGPA record', 'Category certificate where applicable', 'Entrance-examination and admission documents', 'University verification']::text[], 'Through the current ICAR national entrance and admission process', 'https://icar.org.in/', 'https://scholarships.gov.in/public/schemeGuidelines/RevisedGuidelinesforICAR_JRF_SRFandPG_Scholarship_3105_3106.pdf', 'Dates, participating universities and fellowship rates are announced by ICAR for each examination cycle.', '2026-08-28', 'SchemeSetu source pass', 'The captured guideline is dated 2016; current ICAR examination bulletin and rates must control application guidance.'),
(91, 'icar-srf-pgs-agricultural-sciences', 'ICAR Senior Research Fellowship for Postgraduate Studies', 'Indian Council of Agricultural Research, Agricultural Education Division', ARRAY['Education', 'Fellowship', 'Agriculture', 'Doctoral']::text[], 'Ph.D. in agricultural and allied sciences', NULL, 'Candidates with a relevant Master''s degree and required marks/OGPA, selected through the ICAR All India Competitive Examination and admitted to an eligible agricultural university; age and category relaxations follow the current ICAR rules.', 'You may qualify if you have the relevant agricultural Master''s degree, meet the marks and age rules, and are selected for an eligible ICAR doctoral admission.', 'Fellowship and contingency support for a three-year Ph.D. programme at eligible agricultural universities, at rates prescribed by ICAR.', ARRAY['Master''s degree and marks/OGPA record', 'Category certificate where applicable', 'Entrance-examination and admission documents', 'Research/university records', 'University verification']::text[], 'Through the current ICAR national entrance and admission process', 'https://icar.org.in/', 'https://scholarships.gov.in/public/schemeGuidelines/RevisedGuidelinesforICAR_JRF_SRFandPG_Scholarship_3105_3106.pdf', 'Dates, participating universities and fellowship rates are announced by ICAR for each examination cycle.', '2026-08-28', 'SchemeSetu source pass', 'The captured guideline is dated 2016; current ICAR examination bulletin and rates must control application guidance.'),
(92, 'national-fellowship-higher-education-students', 'National Fellowship for Higher Education of Scheduled Tribe Students', 'Ministry of Tribal Affairs', ARRAY['Education', 'Fellowship', 'ST', 'Research']::text[], 'M.Phil. and Ph.D. research in Indian universities', 'As prescribed by the current fellowship guideline and notification', 'Eligible ST students selected under the National Fellowship component for research in Indian universities, subject to the current notification, university admission, research and renewal conditions.', 'You may qualify if you are an eligible ST researcher admitted to an approved M.Phil. or Ph.D. programme and meet the current fellowship notification rules.', 'Fellowship and applicable research support for the approved research tenure, at rates and slot numbers published in the active Ministry/NSP notification.', ARRAY['ST certificate', 'Qualifying degree and marksheets', 'University admission/registration proof', 'Research synopsis', 'Income and bank documents where required']::text[], 'Online through the National Scholarship Portal or the current Ministry process', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/tribalfellowshipguideline.pdf', 'Check the active Ministry and NSP fellowship notification.', '2026-08-28', 'SchemeSetu source pass', 'This is a component-level record separated from the ST higher-education scholarship record; current fellowship rates and slots require notification-level verification.'),
(93, 'national-fellowship-persons-with-disabilities', 'National Fellowship for Persons with Disabilities', 'Department of Empowerment of Persons with Disabilities, Ministry of Social Justice and Empowerment', ARRAY['Education', 'Fellowship', 'Disability', 'Research']::text[], 'M.Phil. and Ph.D. in Indian universities', 'No income ceiling under the captured 2024 umbrella guideline', 'Indian nationals with benchmark disability of at least 40%, valid disability certificate, Aadhaar-based authentication and UDID/UDID enrolment, admitted to an eligible M.Phil. or Ph.D. research programme under the current component rules.', 'You may qualify if you are an Indian researcher with benchmark disability of at least 40%, valid disability/UDID records, and admission to an eligible research programme.', 'Fellowship and applicable research support under the National Fellowship component, with award slots and current rates governed by the active DEPwD notification.', ARRAY['Disability certificate', 'UDID or UDID enrolment', 'Aadhaar authentication', 'Qualifying degree and marksheets', 'University registration/admission proof', 'Research documents', 'Bank details']::text[], 'Through the current Department/NSP process for the National Fellowship component', 'https://scholarships.gov.in/', 'https://scholarships.gov.in/public/schemeGuidelines/DEPDGuidelines_1.pdf', 'Check the active DEPwD/NSP fellowship notification and university conditions.', '2026-08-28', 'SchemeSetu source pass', 'This is a component-level record separated from the umbrella disability scholarship record; current fellowship rates, slots and application route require notification-level verification.')
